void doubleIt(int *n) {   // n is a pointer to int
    *n = *n * 2;          // * reaches the caller's variable
}

void calc(int a, int b, int *sum, int *diff, int *prod) {
    *sum  = a + b;
    *diff = a - b;
    *prod = a * b;
}

int x = 5;
doubleIt(&x);          // send the ADDRESS of x

int s, d, p;
calc(12, 4, &s, &d, &p);   // s = 16, d = 8, p = 48

void safe(int *p) {
    if (p != nullptr) {    // check before using
        *p = 0;
    }
}

