#include <iostream>
using namespace std;

void doubleIt(int *n) {
    *n = *n * 2;
}

int main() {
    int x = 7;
    doubleIt(&x);
    cout << "x = " << x << endl;
    return 0;
}

#include <iostream>
using namespace std;

void swapByAddress(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void doubleIt(int *n) {
    *n = *n * 2;
}

int main() {
    int x = 5, y = 9;
    swapByAddress(&x, &y);
    cout << "x = " << x << ", y = " << y << endl;
    doubleIt(&x);
    cout << "x doubled = " << x << endl;
    return 0;
}

#include <iostream>
using namespace std;

bool divide(int a, int b, int *quotient, int *remainder) {
    if (quotient == nullptr || remainder == nullptr || b == 0) {
        return false;
    }
    *quotient = a / b;
    *remainder = a % b;
    return true;
}

int main() {
    int q = 0, r = 0;
    if (divide(17, 5, &q, &r)) {
        cout << "17 / 5 = " << q << " remainder " << r << endl;
    }
    if (!divide(17, 0, &q, &r)) {
        cout << "Cannot divide by zero" << endl;
    }
    if (!divide(17, 5, nullptr, &r)) {
        cout << "Null pointer rejected" << endl;
    }
    return 0;
}

